insert into public.nodes (id, course_id, stage, title, deps, summary, pitfall, flash, sort) values
  ('net-foundation', 'network', 0, 'Địa chỉ IP, cổng & giao thức', '{}'::text[], 'Trước khi viết chương trình mạng, hãy phân biệt thiết bị được định danh bằng địa chỉ IP, tiến trình giao tiếp qua cổng và quy tắc trao đổi là giao thức.', 'Nhầm rằng một địa chỉ IP chỉ mở được một kết nối TCP tại một thời điểm.', '[{"q":"Hai ứng dụng cùng chạy trên một máy có thể cùng dùng TCP không?","a":"Có. Chúng thường lắng nghe trên các cổng khác nhau, hoặc có những kết nối khác nhau được phân biệt bằng bộ bốn địa chỉ/cổng."},{"q":"Cổng 8080 có bắt buộc là HTTP không?","a":"Không. Cổng chỉ là số; ứng dụng và giao thức ở tầng ứng dụng mới quyết định dữ liệu được trao đổi như thế nào."}]'::jsonb, 0),
  ('net-tcp', 'network', 1, 'Luồng TCP & vòng đời socket', array['net-foundation'], 'TCP cung cấp một luồng byte có thứ tự. Server tạo socket, bind, listen, accept; client dùng connect, sau đó cả hai trao đổi qua send/recv.', 'Cho rằng recv(1024) luôn trả đủ 1024 byte hoặc luôn nhận trọn một tin nhắn.', '[{"q":"Sau accept(), server dùng socket nào để giao tiếp với client?","a":"Socket được accept() trả về; listening socket tiếp tục nhận kết nối mới."},{"q":"Vì sao gửi 100 byte nhưng recv() có thể nhận ít hơn?","a":"TCP là luồng byte, không bảo toàn ranh giới thông điệp; ứng dụng phải đọc lặp và tự phân khung."}]'::jsonb, 1),
  ('net-udp', 'network', 1, 'UDP & ranh giới datagram', array['net-foundation'], 'UDP gửi từng datagram độc lập, chi phí giao thức thấp nhưng không bảo đảm gói đến nơi, đúng thứ tự hoặc chỉ đến một lần.', 'Tưởng rằng UDP luôn nhanh hơn TCP với mọi kiểu ứng dụng, hoặc tự động truyền lại gói thất lạc.', '[{"q":"Hai datagram UDP gửi theo thứ tự A rồi B có luôn đến theo A rồi B?","a":"Không. UDP không bảo đảm thứ tự nhận hay việc gói có đến đích."}]'::jsonb, 2),
  ('net-framing', 'network', 2, 'Thiết kế thông điệp & xử lý lỗi', array['net-tcp', 'net-udp'], 'Một ứng dụng mạng ổn định cần quy ước định dạng dữ liệu, giới hạn kích thước, phản hồi lỗi và thời gian chờ.', 'Dùng một recv() để đọc một file lớn mà không có cơ chế đếm byte hoặc phát hiện kết thúc.', '[{"q":"Làm sao biết khi nào một thông điệp TCP kết thúc?","a":"Phải có quy tắc phân khung do ứng dụng đặt ra, chẳng hạn số byte ở đầu gói hoặc dấu phân cách."}]'::jsonb, 3),
  ('net-concurrency', 'network', 2, 'select, poll, epoll & đa luồng', array['net-tcp'], 'Để server phục vụ nhiều client, ta có thể chờ sự kiện I/O trên nhiều file descriptor hoặc chia công việc qua luồng/tiến trình.', 'Nghĩ rằng select() tự đọc dữ liệu hoặc cứ tạo thêm thread là chắc chắn chạy nhanh hơn.', '[{"q":"select() có đọc dữ liệu hộ chương trình không?","a":"Không. Nó cho biết descriptor có thể thao tác I/O; ứng dụng vẫn cần gọi recv/read."},{"q":"Vì sao cập nhật biến chung từ nhiều thread cần mutex?","a":"Vì phép đọc-sửa-ghi có thể xen kẽ gây race condition và làm mất cập nhật."}]'::jsonb, 4),
  ('net-practice', 'network', 3, 'Thực hành TCP chat server', array['net-framing', 'net-concurrency'], 'Ghép nối socket, phân khung thông điệp và xử lý nhiều kết nối để xây một chatroom đơn giản.', 'Test chỉ với một client rồi kết luận server hoạt động với nhiều client.', '[{"q":"Một bộ test tối thiểu cho chat server nhiều client là gì?","a":"Ít nhất hai client, gửi đồng thời, ngắt đột ngột, tin nhắn dài và kiểm tra server không treo."}]'::jsonb, 5),
  ('net-dns', 'network', 0, 'DNS & getaddrinfo()', array['net-foundation'], 'DNS ánh xạ tên miền thành địa chỉ. Trong lập trình socket C, getaddrinfo() cung cấp danh sách địa chỉ thích hợp cho connect() hoặc bind().', 'Cho rằng DNS luôn trả đúng một IPv4, hoặc nhầm getaddrinfo() là hàm tự kết nối tới máy chủ.', '[{"q":"getaddrinfo() tự mở kết nối TCP tới server chưa?","a":"Chưa. Nó phân giải tên và trả danh sách địa chỉ; ứng dụng dùng socket() và connect() để kết nối."}]'::jsonb, 6),
  ('net-file', 'network', 3, 'Truyền tệp & giao thức DOWNLOAD', array['net-framing', 'net-udp'], 'Truyền tệp cần quy ước tên tệp, kích thước, thứ tự các khối và cách xử lý khi thiếu dữ liệu hoặc mất kết nối.', 'Đọc một lần recv() rồi ghi ngay thành “tệp hoàn chỉnh”; TCP có thể chỉ trả một phần luồng byte.', '[{"q":"Server gửi tệp 1 MB qua TCP: client chỉ gọi recv() một lần có đủ chắc chắn không?","a":"Không. Phải đọc lặp theo kích thước đã thỏa thuận hoặc cho tới khi giao thức báo kết thúc, đồng thời xử lý recv() trả 0 hoặc lỗi."}]'::jsonb, 7),
  ('net-http', 'network', 3, 'HTTP server & xử lý nhiều yêu cầu', array['net-tcp', 'net-concurrency'], 'Tự viết HTTP server giúp hiểu cách đọc request, tạo status line và header, gửi body và đóng hoặc tái sử dụng kết nối đúng quy tắc.', 'Chỉ gửi HTML thô mà thiếu status line/header HTTP hợp lệ, hoặc dùng dữ liệu request làm đường dẫn tệp không kiểm tra.', '[{"q":"Một phản hồi HTTP/1.1 tối thiểu cần bắt đầu bằng gì?","a":"Status line, ví dụ HTTP/1.1 200 OK, tiếp theo là header, dòng trống CRLF và phần body theo định dạng đã xác định."}]'::jsonb, 8),
  ('web-html', 'web', 0, 'HTML ngữ nghĩa & CSS nền tảng', '{}'::text[], 'HTML mô tả cấu trúc và ngữ nghĩa, CSS quyết định cách trình bày; tách hai vai trò để giao diện dễ bảo trì.', 'Dùng div thay button khiến thao tác bàn phím và trình đọc màn hình khó hoạt động.', '[{"q":"Khi một thành phần dùng để thực hiện hành động, nên chọn <a> hay <button>?","a":"<button> cho hành động nội bộ; <a> cho điều hướng đến URL."}]'::jsonb, 9),
  ('web-js', 'web', 1, 'JavaScript & DOM', array['web-html'], 'JavaScript điều khiển trạng thái ứng dụng và tương tác trên trình duyệt thông qua DOM và các sự kiện.', 'Nhầm event handler với kết quả gọi hàm ngay trong lúc gắn sự kiện.', '[{"q":"addEventListener(\"click\", save()) có vấn đề gì?","a":"save() chạy ngay; hãy truyền hàm hoặc callback, ví dụ addEventListener(\"click\", save)."}]'::jsonb, 10),
  ('web-http', 'web', 1, 'HTTP & REST API', array['web-html'], 'Trình duyệt và server trao đổi request/response; method, status code và header thể hiện ý nghĩa của một lời gọi.', 'Tưởng rằng HTTP 200 có nghĩa dữ liệu trả về luôn hợp lệ với mục đích sử dụng.', '[{"q":"HTTP 404 và 500 khác nhau thế nào?","a":"404 là không tìm thấy tài nguyên được yêu cầu; 500 là lỗi phía server."}]'::jsonb, 11),
  ('web-async', 'web', 2, 'fetch, Promise & bất đồng bộ', array['web-js', 'web-http'], 'Lời gọi mạng không trả kết quả ngay; Promise và async/await giúp tổ chức luồng xử lý, trạng thái chờ và lỗi.', 'Đọc dữ liệu từ Promise như đối tượng thông thường trước khi await.', '[{"q":"Vì sao sau fetch cần kiểm tra response.ok?","a":"Fetch chỉ reject khi lỗi mạng hoặc tương tự; phản hồi HTTP 404/500 vẫn có thể resolve."}]'::jsonb, 12),
  ('web-backend', 'web', 2, 'Dữ liệu, API & bảo mật cơ bản', array['web-http', 'web-js'], 'Để dữ liệu chung không mất khi đổi thiết bị, ứng dụng cần API và nơi lưu trữ có kiểm soát truy cập.', 'Dùng localStorage như cơ sở dữ liệu chung hoặc tin rằng ẩn nút là đủ để bảo vệ quyền truy cập.', '[{"q":"Ẩn một nút Admin bằng CSS có bảo vệ API quản trị không?","a":"Không. Server phải kiểm tra xác thực và phân quyền mỗi yêu cầu."}]'::jsonb, 13),
  ('web-project', 'web', 3, 'Dự án: giao diện + API', array['web-async', 'web-backend'], 'Xây một luồng hoàn chỉnh: lấy danh sách, tìm kiếm, xem chi tiết, gửi dữ liệu và xử lý trường hợp lỗi.', 'Chỉ làm trang đẹp mà không thử gửi/lưu dữ liệu hoặc trường hợp backend lỗi.', '[{"q":"Một tính năng được coi là hoàn chỉnh khi nào?","a":"Khi luồng chính và các trạng thái lỗi được kiểm chứng, dữ liệu lưu/đọc đúng và tương tác sử dụng được."}]'::jsonb, 14),
  ('ml-basics', 'ml', 0, 'Học có giám sát & không giám sát', '{}'::text[], 'Học máy tìm quy luật từ dữ liệu. Bài toán có nhãn dùng mẫu đầu ra, còn bài toán không giám sát tìm cấu trúc chưa gắn nhãn.', 'Nhầm clustering với classification chỉ vì cả hai đều chia dữ liệu thành nhóm.', '[{"q":"Dự đoán giá thuê nhà là classification hay regression?","a":"Regression, vì mục tiêu là giá trị số liên tục."}]'::jsonb, 15),
  ('ml-data', 'ml', 1, 'Tiền xử lý & chia tập dữ liệu', array['ml-basics'], 'Dữ liệu thiếu, thang đo khác nhau và rò rỉ thông tin có thể khiến mô hình được đánh giá sai.', 'Chuẩn hóa toàn bộ dữ liệu trước khi chia train/test dẫn tới data leakage.', '[{"q":"Scaler nên fit trên tập nào?","a":"Chỉ tập train; dùng scaler đó để transform validation/test."}]'::jsonb, 16),
  ('ml-regression', 'ml', 2, 'Hồi quy, Ridge & Lasso', array['ml-data'], 'Hồi quy tuyến tính học hệ số để giảm sai số; regularization hạn chế mô hình quá phức tạp bằng hình phạt cho hệ số.', 'Cho rằng Ridge luôn đưa hệ số về 0 giống Lasso.', '[{"q":"Muốn chọn bớt biến bằng cách đưa hệ số về 0, thường xem xét Ridge hay Lasso?","a":"Lasso (L1) có thể tạo hệ số bằng 0; Ridge (L2) thường chỉ thu nhỏ hệ số."}]'::jsonb, 17),
  ('ml-trees', 'ml', 2, 'Cây quyết định & overfitting', array['ml-data'], 'Cây quyết định chia không gian đặc trưng thành các vùng bằng các điều kiện tuần tự, dễ giải thích nhưng có thể quá khớp.', 'Cho rằng độ chính xác train càng cao thì mô hình chắc chắn tổng quát hóa tốt.', '[{"q":"Train accuracy cao nhưng test accuracy thấp thường gợi ý điều gì?","a":"Có thể bị overfitting; cần xem lại đánh giá, phân chia dữ liệu và độ phức tạp mô hình."}]'::jsonb, 18),
  ('ml-svm', 'ml', 2, 'SVM & support vectors', array['ml-data'], 'SVM tìm biên phân tách có margin phù hợp; chỉ một phần các mẫu, gọi là support vectors, quyết định nghiệm.', 'Cho rằng tất cả điểm dữ liệu đều ảnh hưởng trực tiếp đến hàm dự đoán ở dạng đối ngẫu.', '[{"q":"Những mẫu nào đóng góp trực tiếp vào quyết định của SVM dạng đối ngẫu?","a":"Các mẫu có hệ số đối ngẫu khác 0, tức support vectors."}]'::jsonb, 19),
  ('ml-evaluation', 'ml', 3, 'Đánh giá mô hình & chọn metric', array['ml-regression', 'ml-trees', 'ml-svm'], 'Một mô hình tốt cần metric phù hợp bài toán; chỉ một con số accuracy có thể che giấu lỗi nguy hiểm.', 'Dùng accuracy làm metric duy nhất cho dữ liệu có nhãn mất cân bằng mạnh.', '[{"q":"Bài toán cần hạn chế bỏ sót bệnh nhân dương tính thì ưu tiên metric nào?","a":"Recall cho lớp dương thường quan trọng, nhưng vẫn cần cân nhắc precision và chi phí lỗi."}]'::jsonb, 20),
  ('iot-intro', 'iot', 0, 'Kiến trúc hệ thống IoT', '{}'::text[], 'Một hệ thống IoT thường gồm cảm biến hoặc cơ cấu chấp hành, thiết bị xử lý, kênh truyền, dịch vụ phía server và giao diện.', 'Chỉ nghĩ IoT là điều khiển thiết bị bằng điện thoại mà bỏ qua dữ liệu và kết nối.', '[{"q":"Cảm biến nhiệt độ là sensor hay actuator?","a":"Sensor, vì nó đo đại lượng; actuator thực hiện tác động."}]'::jsonb, 21),
  ('iot-hardware', 'iot', 1, 'Cảm biến, lấy mẫu & nhiễu', array['iot-intro'], 'Số đo từ cảm biến cần được lấy mẫu và kiểm tra hợp lý trước khi dùng để ra quyết định.', 'Cho rằng số đọc ADC luôn là đại lượng vật lý đúng mà không cần quy đổi và hiệu chuẩn.', '[{"q":"Vì sao một cảm biến có thể dao động số đo dù môi trường ít thay đổi?","a":"Do nhiễu điện, sai số cảm biến, cách lấy mẫu và đặc điểm môi trường."}]'::jsonb, 22),
  ('iot-network', 'iot', 1, 'Kết nối thiết bị & mạng', array['iot-intro'], 'Thiết bị cần chọn kết nối theo khoảng cách, thông lượng, điện năng và độ ổn định của môi trường.', 'Để khóa API hoặc mật khẩu thiết bị trong mã nguồn công khai.', '[{"q":"Thiết bị mất Wi-Fi thì ứng dụng nên xử lý dữ liệu cảm biến thế nào?","a":"Tùy mục tiêu: lưu tạm, thử gửi lại và thể hiện trạng thái offline; tránh giả định luôn có kết nối."}]'::jsonb, 23),
  ('iot-mqtt', 'iot', 2, 'MQTT, broker & topic', array['iot-network'], 'MQTT dựa trên publish/subscribe: thiết bị publish tin lên topic qua broker, ứng dụng subscribe để nhận dữ liệu.', 'Nhầm broker là bộ cảm biến hoặc cho rằng QoS 2 nghĩa là hệ thống không bao giờ lỗi.', '[{"q":"Nếu thiết bị publish vào home/room1/temp, ai nhận được?","a":"Client đang subscribe topic phù hợp, thông qua MQTT broker và theo chính sách quyền truy cập."}]'::jsonb, 24),
  ('iot-dashboard', 'iot', 2, 'Thu thập & hiển thị dữ liệu', array['iot-hardware', 'iot-mqtt'], 'Dữ liệu cảm biến chỉ hữu ích khi kèm thời gian đo, đơn vị, chất lượng và ngữ cảnh.', 'Biểu đồ nối các điểm lỗi hoặc thiếu như thể tín hiệu luôn liên tục và đáng tin.', '[{"q":"Vì sao nên lưu timestamp ở phía thiết bị hoặc khi nhận dữ liệu?","a":"Để biết thời điểm đo, nhận diện độ trễ và phân tích dữ liệu theo thời gian."}]'::jsonb, 25),
  ('iot-project', 'iot', 3, 'Thực hành: giám sát nhiệt độ', array['iot-dashboard'], 'Thiết kế luồng cảm biến → thiết bị → MQTT → dịch vụ → dashboard và kiểm thử cả khi mất kết nối.', 'Hiển thị số cũ mà không thông báo đã mất tín hiệu.', '[{"q":"Một dashboard hiển thị 28°C từ một giờ trước có ổn không?","a":"Không nếu không chỉ ra dữ liệu đã cũ và trạng thái kết nối, vì người xem có thể hiểu lầm đó là số đo hiện tại."}]'::jsonb, 26)
